                log::info!(
                    "Webview page load: url={}, event={:?}",
                    payload.url(),
                    payload.event()
                );
            })
            .build()
            .map_err(|e| {
                log::error!("Failed to create dev-key webview: {}", e);
            });
        }
    }

    log::info!("CipherBox Desktop setup complete (tray icon active)");
    Ok(())
