async function init(): Promise<void> {
  console.log('CipherBox Desktop initializing...');

  const appDiv = document.getElementById('app');

  // Show loading state
  if (appDiv) {
    appDiv.innerHTML = loadingHtml('Initializing CipherBox...');
  }

  // Step 1: Check for dev-key mode (debug builds only — command not
  // registered in release builds, so invoke will reject)
  let devKey: string | null = null;
  try {
    devKey = await invoke('get_dev_key');
  } catch {
    // Expected in release builds where the command isn't registered
  }
  if (devKey) {
    if (appDiv) {
      appDiv.innerHTML = loadingHtml('Dev mode: authenticating with provided key...');
    }
    try {
      await handleDevKeyAuth(devKey);
      handleAuthSuccess(appDiv);
      return;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error('Dev-key auth failed:', err);
      // Report to Rust logger so CI can see webview errors
      invoke('log_js_error', { context: 'handleDevKeyAuth', message: msg }).catch(() => {});
      if (appDiv) {
        appDiv.innerHTML = errorHtml(msg || 'Dev-key authentication failed');
      }
      return;
    }
  }

  // Step 2: Try silent refresh from Keychain
  let silentRefreshOk = false;
  try {
    const refreshed: boolean = await invoke('try_silent_refresh');
    if (refreshed) {
      console.log('API session refreshed from Keychain');
      silentRefreshOk = true;
    }
  } catch (err) {
    console.warn('Silent refresh failed:', err);
    // Not an error -- just means we need full login
