/// Flush file data (no-op).
pub fn handle_flush(reply: ReplyEmpty) {
    reply.ok();
}

/// Check file access permissions.
pub fn handle_access(
    fs: &CipherBoxFS,
    ino: u64,
    mask: i32,
    reply: ReplyEmpty,
) {
    if fs.inodes.get(ino).is_none() {
        reply.error(libc::ENOENT);
        return;
