                    .count() as u32;
                if failed > 0 {
                    (self.status_callback)(SyncStatus::WriteParked { pending, failed });
                    return;
                }
            }
            Err(e) => {
                log::warn!("Journal read failed during sync cycle: {} — proceeding to Idle", e);
            }
        }
    }

    (self.status_callback)(SyncStatus::Idle);
